CREATE TRIGGER commerce_order_touch BEFORE UPDATE ON commerce.commerce_order FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER order_line_touch BEFORE UPDATE ON commerce.order_line FOR EACH ROW EXECUTE FUNCTION core.touch();
CREATE TRIGGER payment_intent_touch BEFORE UPDATE ON commerce.payment_intent FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE TRIGGER payment_transaction_append_only BEFORE UPDATE OR DELETE ON commerce.payment_transaction FOR EACH ROW EXECUTE FUNCTION core.forbid_mutation();
CREATE TRIGGER commerce_reference_touch BEFORE UPDATE ON commerce.commerce_reference FOR EACH ROW EXECUTE FUNCTION core.touch_versioned();
CREATE UNIQUE INDEX commerce_order_number_uq ON commerce.commerce_order (tenant_id, property_id, order_number) WHERE order_number IS NOT NULL;
CREATE UNIQUE INDEX commerce_order_receipt_uq ON commerce.commerce_order (tenant_id, property_id, receipt_number) WHERE receipt_number IS NOT NULL;

-- Lines of a Draft order (a cart) may be removed; once the order is placed its lines are evidence.
CREATE FUNCTION commerce.order_line_delete_only_draft() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM commerce.commerce_order o
                    WHERE o.tenant_id = OLD.tenant_id AND o.commerce_order_id = OLD.commerce_order_id
                      AND o.status = 'Draft') THEN
        RAISE EXCEPTION 'order_line can be deleted only while its order is Draft' USING ERRCODE = '42501';
    END IF;
    RETURN OLD;
END $$;
CREATE TRIGGER order_line_delete_only_draft BEFORE DELETE ON commerce.order_line
    FOR EACH ROW EXECUTE FUNCTION commerce.order_line_delete_only_draft();
CREATE UNIQUE INDEX payment_intent_provider_uq ON commerce.payment_intent (tenant_id, provider_code, provider_reference) WHERE provider_reference IS NOT NULL;
CREATE INDEX payment_intent_appointment_ix ON commerce.payment_intent (tenant_id, appointment_id, purpose);
